Here is the commit message:
bnxt_en: Skip ethtool RSS context configuration in ifdown
 state

The current implementation requires the ifstate to be up when
configuring the RSS contexts.  It will try to fetch the RX ring
IDs and will crash if it is in ifdown state.  Return error if
!netif_running() to prevent the crash.

An improved implementation is in the works to allow RSS contexts
to be changed while in ifdown state.

Fixes: b3d0083caf9a ("bnxt_en: Support RSS contexts in ethtool .{get|set}_rxfh()")
Reviewed-by: Kalesh AP <kalesh-anakkur.purayil@broadcom.com>
Reviewed-by: Somnath Kotur <somnath.kotur@broadcom.com>
Signed-off-by: Pavan Chebbi <pavan.chebbi@broadcom.com>
Signed-off-by: Michael Chan <michael.chan@broadcom.com>
Reviewed-by: Jacob Keller <jacob.e.keller@intel.com>
Link: https://lore.kernel.org/r/20240409215431.41424-2-michael.chan@broadcom.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The bug occurs because the implementation attempts to configure RSS contexts by fetching RX ring IDs when the network interface is in the `ifdown` state. This leads to a crash since the necessary resources are not available when the interface is not running.

Here is the patch:

 static int bnxt_set_rxfh_context(struct bnxt *bp,
 				 struct ethtool_rxfh_param *rxfh,
 				 struct netlink_ext_ack *extack)
 {
 	u32 *rss_context = &rxfh->rss_context;
 	struct bnxt_rss_ctx *rss_ctx;
 	struct bnxt_vnic_info *vnic;
 	bool modify = false;
 	int bit_id;
 	int rc;

 	if (!BNXT_SUPPORTS_MULTI_RSS_CTX(bp)) {
 		NL_SET_ERR_MSG_MOD(extack, "RSS contexts not supported");
 		return -EOPNOTSUPP;
 	}

+	if (!netif_running(bp->dev)) {
+		NL_SET_ERR_MSG_MOD(extack, "Unable to set RSS contexts when interface is down");
+		return -EAGAIN;
+	}
+
 	if (*rss_context != ETH_RXFH_CONTEXT_ALLOC) {
 		rss_ctx = bnxt_get_rss_ctx_from_index(bp, *rss_context);
 		if (!rss_ctx) {
 			NL_SET_ERR_MSG_FMT_MOD(extack, "RSS context %u not found",
 					       *rss_context);
 			return -EINVAL;
 		}
 		if (*rss_context && rxfh->rss_delete) {
 			bnxt_del_one_rss_ctx(bp, rss_ctx, true);
 			return 0;
 		}
 		modify = true;
 		vnic = &rss_ctx->vnic;
 		goto modify_context;
 	}

 	if (bp->num_rss_ctx >= BNXT_MAX_ETH_RSS_CTX) {
 		NL_SET_ERR_MSG_FMT_MOD(extack, "Out of RSS contexts, maximum %u",
 				       BNXT_MAX_ETH_RSS_CTX);
 		return -EINVAL;
 	}

 	if (!bnxt_rfs_capable(bp, true)) {
 		NL_SET_ERR_MSG_MOD(extack, "Out hardware resources");
 		return -ENOMEM;
 	}

 	rss_ctx = bnxt_alloc_rss_ctx(bp);
 	if (!rss_ctx)
 		return -ENOMEM;

 	vnic = &rss_ctx->vnic;
 	vnic->flags |= BNXT_VNIC_RSSCTX_FLAG;
 	vnic->vnic_id = BNXT_VNIC_ID_INVALID;
 	rc = bnxt_alloc_rss_ctx_rss_table(bp, rss_ctx);
 	if (rc)
 		goto out;

 	rc = bnxt_alloc_rss_indir_tbl(bp, rss_ctx);
 	if (rc)
 		goto out;

 	bnxt_set_dflt_rss_indir_tbl(bp, rss_ctx);
 	memcpy(vnic->rss_hash_key, bp->rss_hash_key, HW_HASH_KEY_SIZE);

 	rc = bnxt_hwrm_vnic_alloc(bp, vnic, 0, bp->rx_nr_rings);
 	if (rc) {
 		NL_SET_ERR_MSG_MOD(extack, "Unable to allocate VNIC");
 		goto out;
 	}

 	rc = bnxt_hwrm_vnic_set_tpa(bp, vnic, bp->flags & BNXT_FLAG_TPA);
 	if (rc) {
 		NL_SET_ERR_MSG_MOD(extack, "Unable to setup TPA");
 		goto out;
 	}
 modify_context:
 	bnxt_modify_rss(bp, rss_ctx, rxfh);

 	if (modify)
 		return bnxt_hwrm_vnic_rss_cfg_p5(bp, vnic);

 	rc = __bnxt_setup_vnic_p5(bp, vnic);
 	if (rc) {
 		NL_SET_ERR_MSG_MOD(extack, "Unable to setup TPA");
 		goto out;
 	}

 	bit_id = bitmap_find_free_region(bp->rss_ctx_bmap,
 					 BNXT_RSS_CTX_BMAP_LEN, 0);
 	if (bit_id < 0) {
 		rc = -ENOMEM;
 		goto out;
 	}
 	rss_ctx->index = (u16)bit_id;
 	*rss_context = rss_ctx->index;

 	return 0;
 out:
 	bnxt_del_one_rss_ctx(bp, rss_ctx, true);
 	return rc;
 }



